css:
 .auto-slide-carousel {
  width: 600px;
  max-width: 100%;
  position: relative;
  margin: 0 auto;
  padding: 0;
  background: #ffe4e1;
  box-sizing: border-box;
}

 .review-box {
  width: 92%;
  margin: 4% auto;
  padding: 0;
  border-radius: 20px;
  background-color: #ffffff;
  overflow: hidden;
  box-sizing: border-box;
}

 .review-head {
  display: flex;
  align-items: center;
  padding: 20px 20px 5px;
}

 .review-head .image {
  width: 25%;
  max-width: 160px;
  flex-shrink: 0;
}

 .review-head .image img {
  width: 50px;
  height: auto;
  margin: 0 auto;
  padding-right: 10px;
}

 .review-head .info {
  width: 75%;
}

 .review-head .info p {
  font-size: 16px;
  margin: 0;
  line-height: 1.3;
}

 .review-head .info .underline {
  text-decoration: underline;
}

 .star {
  width: 91px;
  height: 19px;
  margin-right: 10px;
}

 .star01 {
  background: url('/uploads/1efd75d52a5890b7618e81933ba49142ec7b0f41f7bfb24983e989cdd4612bd9.png');
}

 .star02 {
  background: url('/uploads/f8fb8ee2c1253cec270f94934af8a70ba5035a89004bc0cf895764be4a63b596.png');
}

 .star03 {
  background: url('/uploads/fa39a2b97421d8ab04d9b29fa1fa3c916c65ee3c5c393f327a3bdb780511b842.png');
}

 .star04 {
  background: url('/uploads/d5984c3e7a1979755b1a4a427db50f05ab0bb932b1c6b99ce0a3f3024a76c26e.png');
}

 .star05 {
  background: url('/uploads/9e5cbf16a04a40ad999fb71b7063b6da7bf044b75cf3663999c3ea249e00e11e.png');
}

 .review-body {
  padding: 5px 20px 20px;
}

 .review-body p {
  font-size: 16px;
  margin: 0;
  line-height: 1.5;
}

 .swiper {
  margin-left: auto;
  margin-right: auto;
  position: relative;
  overflow: hidden;
  list-style: none;
  padding: 0;
  z-index: 1;
}

 .swiper-pointer-events {
  touch-action: pan-y;
}

 .swiper-wrapper {
  position: relative;
  width: 100%;
  height: auto;
  z-index: 1;
  display: flex;
  -webkit-transform: translate3d(0px, 0, 0);
  transform: translate3d(0px, 0, 0);
  transition-property: -webkit-transform;
  transition-property: transform;
  transition-property: transform, -webkit-transform;
  box-sizing: content-box;
}

 .swiper-slide {
  flex-shrink: 0;
  width: 100%;
  height: 100%;
  position: relative;
  transition-property: -webkit-transform;
  transition-property: transform;
  transition-property: transform, -webkit-transform;
}

 .htmlValue .swiper-wrapper {
  flex-direction: column;
}

.widget-container {
  font-size: 14px;
  width: min(750px, 100%);
  margin-inline: auto;
  line-height: 1.35;
  color: #333;
  position: relative;
}

.widget-container>* {
  box-sizing: border-box;
}


.tab-lists {
  display: flex;
  gap: 0.15em;
}

.tab-lists .list {
  width: calc(100% / 4);
  aspect-ratio: 3/1;
  text-align: center;
  background-color: #e69f88;
  border-radius: 0.5em;
  display: grid;
  place-items: center;
  box-sizing: border-box;
  font-weight: 600;
}

.tab-lists .list.is-selected {
  pointer-events: none;
}

.tab-lists .list.is-selected,
.tab-lists .list:hover {
  background-color: #d54e25;
  color: #fff;
  transition: background-color 0.5s;
}

.tab-contents {
  margin-top: 2.5em;
}

.comment-item {
  background-color: #fff;
  border: solid 1px #dadada;
  border-radius: 0.5em;
  padding: 1em;
  box-sizing: border-box;
  font-size: 0.9em;
  cursor: pointer;
}

.comment-item+.comment-item {
  margin-top: 1em;
}

.comment-item .item-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.comment-item .item-meta .user-name {
  font-weight: bold;
  display: flex;
  align-items: center;
  gap: 0.25em;
}

.comment-item .item-meta .user-name::before {
  content: "";
  display: block;
  width: 2em;
  aspect-ratio: 1;
  background: url("/uploads/6637f6a1eaa5240b2464ca488f8ff9d2ccacf66817f2ef8eb2c1303752f0004b.png") no-repeat center/contain;
}

.comment-item .item-content {
  display: grid;
  grid-template-columns: 10em auto;
  gap: 1em;
  margin-top: 0.5em;
}

.comment-item .item-image img {
  aspect-ratio: 1;
  width: 100%;
  object-fit: cover;
}

.comment-item .item-text {
  width: 100%;
  position: relative;
  max-height: 10em;
  overflow: hidden;
  text-align: justify;
}

.comment-item .item-text::after {
  content: "";
  display: block;
  position: absolute;
  width: 100%;
  height: 100%;
  background: linear-gradient(transparent, #fff);
  bottom: 0;
  left: 0;
  z-index: 1;
  pointer-events: none;
}

.comment-item .more-read {
  width: 100%;
  position: absolute;
  bottom: 0;
  z-index: 2;
  display: grid;
  place-items: center;
  display: none;
  cursor: pointer;
}



.widget-container .modal-overlay {
  content: "";
  position: fixed !important;
  width: 100%;
  height: 100%;
  background: rgba(0, 0, 0, 0.5);
  position: absolute;
  top: 0;
  left: 0;
  z-index: 999;
  cursor: pointer;
}

.widget-container .modal-content {
  opacity: 0;
  position: fixed;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  z-index: 1000;
  padding: 2.5em;
  font-size: 1.2em;
  width: min(90%, 1000px) !important;
  overflow-y: scroll;
  -ms-overflow-style: none;
  scrollbar-width: none;
  animation: fadeIn 0.5s 0.25s forwards;
  transition: 0.5s;
  cursor: default;
  max-height: 90vh;
}

.widget-container .modal-content::-webkit-scrollbar {
  display: none;
}

.widget-container .modal-content .item-content {
  grid-template-columns: 15em auto;
}

.widget-container .modal-content .item-text {
  max-height: 15em;
  line-height: 1.6;
  transition: max-height 0.5s;
}

.widget-container .modal-content .item-text.is-readed {
  max-height: 9999px;
}

.widget-container .modal-content .item-text.is-readed .more-read {
  display: none;
}

.widget-container .modal-content .item-text.is-readed::after {
  display: none;
}

.widget-container .modal-content .more-read {
  display: grid;
}

.widget-container .modal-close {
  width: 3em;
  aspect-ratio: 1/1;
  background-color: transparent;
  position: fixed;
  top: 5%;
  right: 5%;
  z-index: 1000;
  margin: 0;
}

.widget-container .modal-close::before,
.widget-container .modal-close::after {
  content: "";
  width: 5px;
  height: 55%;
  background: #fff;
  position: absolute;
  top: 50%;
  left: 45%;
  z-index: 1000;
  pointer-events: none;
  rotate: 45deg;
  translate: 0% -50%;
  transition: 0.3s;
}

.widget-container .modal-close::after {
  left: unset;
  right: 55%;
  rotate: -45deg;
  translate: 100% -50%;
}

.is-hidden {
  display: none;
}

button {
  border: none;
  background: none;
  cursor: pointer;
  outline: none;
  font-size: unset;
}

@media (max-width: 580px) {
  .widget-container .modal-content {
    padding: 1.5em;
  }

  .widget-container .modal-content .item-content {
    grid-template-columns: 100%;
  }

  .widget-container .modal-content .item-text.is-readed {
    max-height: 999999px;
  }

  .widget-container .modal-close {
    background: #000;
    pointer-events: all;
  }
}



@keyframes fadeIn {
  0% {
    opacity: 0;
  }

  100% {
    opacity: 1;
  }
}

.EDITABLE .tab-contents {
  width: 100%;
  display: grid;
  grid-template-columns: repeat(4, 100%);
  overflow-x: scroll;
  scroll-snap-type: x mandatory;
}

.widget-container {
  font-size: 14px;
  width: min(90%, 750px);
  margin-inline: auto;
  line-height: 1.35;
  color: #333;
  position: relative;
}

.widget-container>* {
  box-sizing: border-box;
}

.widget-item.is-modal-open::before {
  content: "";
  width: 100%;
  height: 100%;
  background: rgba(0, 0, 0, 0.8);
  position: fixed;
  top: 0;
  left: 0;
  z-index: 1000;
  pointer-events: none;
}

.slide-hopup-item {
  box-sizing: border-box;
  background: #fff;
  border: solid 2px #efcdbb;
  padding: 0.75em;
  cursor: pointer;
}

.slide-hopup-item>*+* {
  margin-top: 1.5em;
}

.slide-hopup-item-meta {
  display: grid;
  grid-template-columns: max(1.5em, 5%) auto auto;
  gap: 1em 0.5em;
  position: relative;
  overflow: hidden;
}

.slide-hopup-item-meta::after {
  content: "";
  width: 100%;
  height: 100px;
  background: linear-gradient(to bottom, transparent, #fff);
  position: absolute;
  bottom: 0;
  left: 0;
}

.slide-hopup-item-meta .avater {
  width: 100%;
  aspect-ratio: 1/1;
  background: url("/uploads/f940473005b966f4b6b7c9c3dbe538faea476fd3161083e204c7f8f391695250.svg") no-repeat center center/contain;
  border-radius: 50%;
  overflow: hidden;
  grid-column: 1/1;
  filter: hue-rotate(180deg);
}

.slide-hopup-item-meta .username {
  grid-column: 2/4;
  align-self: center;
  font-weight: bold;
  font-size: 0.9em;
}

.slide-hopup-item-meta .comment {
  overflow: hidden;
  grid-column: 1/-1;
  max-height: 5vh;
}

.slide-hopup-item-meta .comment p {
  font-size: 0.8em;
}

.slide-hopup-item-meta .comment p+p {
  margin-top: 0.5em;
}

.slide-hopup-item.is-modal-item {
  opacity: 0;
  animation: slide-hopup-item-show 0.5s 0.5s forwards;
  position: fixed;
  z-index: 1000;
  width: min(90%, 750px) !important;
  height: max(90vh, 750px) !important;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  overflow-y: scroll;
  padding: 2.5em;
  -ms-overflow-style: none;
  scrollbar-width: none;
}

.slide-hopup-item.is-modal-item::-webkit-scrollbar {
  display: none;
}

.slide-hopup-item.is-modal-item .slide-hopup-item-image img {
  width: 100%;
  height: auto;
}

.slide-hopup-item.is-modal-item .slide-hopup-item-meta .comment {
  max-height: 100%;
}

.slide-hopup-item.is-modal-item .slide-hopup-item-meta .comment p {
  font-size: 1em;
}

.slide-hopup-item.is-modal-item .slide-hopup-item-meta .comment p+p {
  margin-top: 1.5em;
}

.slide-hopup-item.is-modal-item .slide-hopup-item-meta::after {
  display: none;
}

.slide-hopup-close {
  width: 3em;
  aspect-ratio: 1/1;
  background-color: transparent;
  position: absolute;
  top: 0;
  right: 0;
  z-index: 1000;
  margin: 0;
}

.slide-hopup-close::before,
.slide-hopup-close::after {
  content: "";
  width: 5px;
  height: 55%;
  background: #000;
  position: absolute;
  top: 50%;
  left: 50%;
  z-index: 1000;
  pointer-events: none;
  rotate: 45deg;
  translate: 0% -50%;
  transition: 0.3s;
}

.slide-hopup-close::after {
  left: unset;
  right: 50%;
  rotate: -45deg;
  translate: 100% -50%;
}

.swiper-button-next,
.swiper-button-prev {
  color: #ff5c63;
  z-index: unset;
}

.swiper-button-next {
  right: -30px;
}

.swiper-button-prev {
  left: -30px;
}

.swiper-button-next img,
.swiper-button-prev img {
  width: 100%;
}

img {
  width: 100%;
  height: auto;
}


@keyframes slide-hopup-item-show {
  0% {
    opacity: 0;
  }

  100% {
    opacity: 1;
  }
}

.EDITABLE .swiper {
  position: relative;
  overflow: unset;

}

.EDITABLE .swiper::after {
  width: 100%;
  text-align: center;
  line-height: 1;
  font-size: .8em;
  position: absolute;
  bottom: -2em;
  color: #656565;
}

.EDITABLE .swiper-wrapper {
  overflow-x: scroll;
  scroll-snap-type: x mandatory;
  height: auto;
}

.EDITABLE .swiper-slide {
  margin: 0 10px;
  scroll-snap-align: start;
  width: 75%;
  overflow: clip;
}

.EDITABLE .slide-hopup-item-meta .comment {
  max-height: 100%;
}

.EDITABLE .slide-hopup-item-meta::after {
  display: none;
}

.EDITABLE .swiper-button-prev,
.EDITABLE .swiper-button-next {
  top: 25% !important;
}

.repute__wrap {
  font-size: 16px;
  max-width: 750px;
  margin-inline: auto;
  gap: 25px;
  width: 100%;
  border-radius: 8px 8px 0 0;
  overflow: hidden;
}

@media (max-width: 500px) {
  .repute__wrap {
    font-size: 3.4vw;
  }
}

.repute__head {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  font-size: 20px;
  padding: 2% 3% 2% 0;
  font-weight: bold;
  border-bottom: solid 2px #1368b0;
}

.repute__i {
  width: 30px;
  aspect-ratio: 1/1;
  background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512"><!--! Font Awesome Pro 6.2.1 by @fontawesome - https://fontawesome.com License - https://fontawesome.com/license (Commercial License) Copyright 2022 Fonticons, Inc. --><path fill="%231368b0" d="M256 448c141.4 0 256-93.1 256-208S397.4 32 256 32S0 125.1 0 240c0 45.1 17.7 86.8 47.7 120.9c-1.9 24.5-11.4 46.3-21.4 62.9c-5.5 9.2-11.1 16.6-15.2 21.6c-2.1 2.5-3.7 4.4-4.9 5.7c-.6 .6-1 1.1-1.3 1.4l-.3 .3 0 0 0 0 0 0 0 0c-4.6 4.6-5.9 11.4-3.4 17.4c2.5 6 8.3 9.9 14.8 9.9c28.7 0 57.6-8.9 81.6-19.3c22.9-10 42.4-21.9 54.3-30.6c31.8 11.5 67 17.9 104.1 17.9zM128 272c-17.7 0-32-14.3-32-32s14.3-32 32-32s32 14.3 32 32s-14.3 32-32 32zm128 0c-17.7 0-32-14.3-32-32s14.3-32 32-32s32 14.3 32 32s-14.3 32-32 32zm160-32c0 17.7-14.3 32-32 32s-32-14.3-32-32s14.3-32 32-32s32 14.3 32 32z"/></svg>');
}

.repute__content {
  padding: 0 5%;
  overflow: hidden;
  position: relative;
  background-color: none;
}

@media screen and (max-width: 767px) {
  .repute__content {
    padding: 0 7.5%;
  }
}

.repute__content [class*=repute-swiper-button-] {
  width: 30px;
  height: 30px;
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  left: 0%;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  background: #1368b0;
  border-radius: 50%;
  overflow: hidden;
}

.repute__content [class*=repute-swiper-button-]::before {
  content: "";
  width: 100%;
  height: 100%;
  scale: .5;
  background-color: #FFF;
  clip-path: polygon(75% 0, 40% 50%, 75% 100%, 55% 100%, 20% 50%, 55% 0);
}

.repute__content .repute-swiper-button-next {
  left: unset;
  right: 0%;
}

.repute__content .repute-swiper-button-next::before {
  clip-path: polygon(35% 0, 77% 50%, 35% 100%, 15% 100%, 58% 50%, 15% 0);
}

.repute__inner {
  margin: 2em 0;
  overflow: hidden;
  position: relative;
}

.repute__ratings {
  position: relative;
  font-size: 22px;
  min-height: 22px;
  line-height: 1;
  margin-bottom: 5px;
}

.repute__ratings::before,
.repute__ratings::after {
  content: "★★★★★";
  color: #ffe683;
  position: absolute;
  top: 0;
  left: 0;
}

.repute__ratings::after {
  color: #ffb448;
  overflow: hidden;
  white-space: nowrap;
}

.repute__item {
  border: solid 1px #999;
  box-sizing: border-box;
  border-radius: 1em;
  padding: 1em;
}

.repute__item:has(img) {
  display: grid;
  align-items: center;
  gap: 5px;
  grid-template-columns: 3.5em auto;
  grid-template-rows: 1.5em auto auto;
}

.repute__item>picture {
  grid-column: 1 / 2;
  grid-row: 1 / 3;
}

.repute__item>img,
.repute__item>picture img {
  width: 3.5em;
  aspect-ratio: 1;
  object-fit: contain;
  grid-column: 1 / 2;
  grid-row: 1 / 3;
  border-radius: 50%;
  background-color: #EEE;
}

.repute__title {
  font-size: 1.15em;
  font-weight: bold;
  grid-column: 2 / 3;
  line-height: 1;
}

.repute__comment {
  text-align: justify;
  grid-column: 1 / -1;
  border-top: solid 1px #999;
  padding-top: .5em;
}

.repute__ratings[data-ratings="0"]::after {
  width: 0px;
}

.repute__ratings[data-ratings="0.5"]::after {
  width: calc(22px * 0.5);
}

.repute__ratings[data-ratings="1"]::after {
  width: 22px;
}

.repute__ratings[data-ratings="1.5"]::after {
  width: calc(22px * 1.5);
}

.repute__ratings[data-ratings="2"]::after {
  width: calc(22px * 2);
}

.repute__ratings[data-ratings="2.5"]::after {
  width: calc(22px * 2.5);
}

.repute__ratings[data-ratings="3"]::after {
  width: calc(22px * 3);
}

.repute__ratings[data-ratings="3.5"]::after {
  width: calc(22px * 3.5);
}

.repute__ratings[data-ratings="4"]::after {
  width: calc(22px * 4);
}

.repute__ratings[data-ratings="4.5"]::after {
  width: calc(22px * 4.5);
}

.repute__ratings[data-ratings="5"]::after {
  width: calc(22px * 5);
}

.swiper-wrapper {
  position: relative;
  width: 100%;
  height: auto !important;
  z-index: 1;
  display: flex;
  transition-property: transform;
  box-sizing: content-box;
}

.swiper-android .swiper-slide,
.swiper-wrapper {
  transform: translate3d(0px, 0, 0);
}

.swiper-slide {
  flex-shrink: 0;
  width: 100%;
  height: auto !important;
  position: relative;
  transition-property: transform;
}

.repute.js-repute-slide.init .swiper-wrapper {
  overflow-x: scroll;
  scroll-snap-type: x mandatory;
}

.repute.js-repute-slide.init .swiper-slide {
  scroll-snap-align: start;
}

blockquote {
  position: relative;
  margin: 0 0em 1.5em;
  padding-top: 45px;
  padding-right: 15px;
  padding-bottom: 15px;
  padding-left: 15px;
  border: 2px solid #CCCCCC;
  background-color: #FEEEED;
  z-index: 1;
}

blockquote p {
  position: relative;
  z-index: 3;
}

blockquote:before {
  content: "“";
  font-size: 500%;
  line-height: 0.8em;
  font-family: 'Times New Roman', "ＭＳ Ｐ", sans-serif;
  color: #CCCCCC;
  position: absolute;
  left: 0;
  top: 0;
  z-index: 2;
}

blockquote:after {
  content: "”";
  font-size: 500%;
  line-height: 0em;
  font-family: 'Times New Roman', "ＭＳ Ｐ", sans-serif;
  color: #CCCCCC;
  position: absolute;
  right: 0;
  bottom: 0;
  z-index: 2;
}

blockquote p {
  margin: 1em 0;
}

.b-marker {
  /*マーカーハイライト部分の色を変更する場合下記カラーコード変更*/
  background: linear-gradient(transparent 60%, #cce5ff 0%);
}

.tweet__area {
  border: 1px solid #efefef;
  border-top: 20px solid #44A5CB;
}

.box {
  /*最大幅の指定。max-widthで指定した値の最大幅以上には広がらずに表示*/
  max-width: 580px;
  display: flex;
  font-size: 14px;
  line-height: 1.4;
  border-bottom: 1px solid #ebeef0;
  padding-bottom: 12px;
  box-sizing: border-box;
  margin: 0 auto;
}

.container-left {
  padding: 11px;
  background-color: #fff;
}

.container-right {
  padding: 11px 11px 0 0;
  background-color: #fff;
}

.container-right a {
  color: #44A5CB;
  font-weight: bold;
}

.img {
  width: 100%;
  height: auto;
}

ul.unstyled {
  list-style: none;
  margin: 0;
  padding: 0;
}

ul.flex-list {
  display: flex;
  justify-content: space-between;
}

.user-wrapper {
  display: flex;
}

.user-icon-wrapper {
  width: 46px;
}

.user-icon-wrapper img {
  width: 46px;
  max-width: 46px;
  height: 46px !important;
  object-fit: cover;
}

.user-icon {
  border-radius: 50%;
}

.user-name-wrapper {
  display: flex;
  margin-bottom: 6px;
}

.user-name {
  font-weight: 600;
}

