/* ウィジェット全体 */
.l-review__appli__list {
  /* 横幅 */
  width: 100%;
  /* 最大幅 */
  max-width: 980px;
  /* 文字色 */
  color: #333;
  /* 文字サイズ */
  font-size: 12px;
  /* 外側余白|上|auto=自動|下| */
  margin: 0 auto 22px;
  /* 行間 */
  line-height: 1.8;
  /* 枠線|太さ|タイプ|色| */
  border: 2px solid #584f5b;
  /* 角丸 */
  border-radius: 4px;
}

