  /* 文字サイズ */
  font-size: 16px;
  /* 背景色 */
  background-color: #584f5b;
  /* 文字色 */
  color: #fff;
  /* 内側余白|上|左右|下| */
  padding: 0.2em 0.8em 0.2em 32px;
  background: #584f5b url(/uploads/e485d55ba633212c4d4ff913c2df06296d843aaf81a34eedbdc2bfd27c8ac029.png) no-repeat 12px
    center / 15px 16px;
}

/* リスト全体 */
.l-review__appli__list__ul {
  /* 内側余白 */
  margin: 0;
  /* 外側余白 */
  padding: 0.4em 0.8em;
  list-style-type: none;
}

/* リストそれぞれ */
.l-review__appli__list__ul__li {
  /* 内側余白|上|左|下|右| */
  margin: 0 0 5px 0;
  /* 外側余白|上|左|下|右| */
}

.l-review__appli__list__ul__li:not(:last-of-type) {
  /* 枠線下|太さ|タイプ|色| */
  border-bottom: 1.5px solid #eee;
  padding: 0 0 1.4em 0;
}

/*「総合評価」の★の設定*/
.l-review__appli__list__rate {
  /*★の大きさ*/
  font-size: 18px;
  /*はみ出た要素を非表示にする*/
  overflow: hidden;
  /* 行間 */
  line-height: 1.8;
  /* 外側余白|上下左右| */
  margin: 0;
  position: relative;
  display: inline-block;
}

/*総合評価に使用する記号等*/
.l-review__appli__list__rate:before,
.l-review__appli__list__rate:after {
  content: "★★★★★";
}

/*星の色が薄い部分*/
.l-review__appli__list__rate:before {
  /*文字色*/
  color: #ccc;
}

/*星の色が黄色い部分*/
.l-review__appli__list__rate:after {
  /*横位置（左基準）*/
  left: 0;
  /*縦位置（上基準）*/
  top: 0;
  /*文字色*/
  color: #f5bc55;
  /*はみ出た要素を非表示にする*/
  overflow: hidden;
  position: absolute;
}

/*色あり記号にする設定*/
.l-review__appli__list__rate.star1:after {
  /*1文字分*/
  width: 1em;
}

.l-review__appli__list__rate.star2:after {
  width: 2em;
}

.l-review__appli__list__rate.star3:after {
  width: 3em;
}

.l-review__appli__list__rate.star4:after {
  width: 4em;
}

.l-review__appli__list__rate.star5:after {
  width: 5em;
