  width: 16.6666666667vw;
  height: 16.6666666667vw !important;
  max-width: 100px;
  max-height: 100px;
  border-radius: 50%;
  -o-object-fit: cover;
  object-fit: cover;
}

.box-blink .inner-top .img figcaption {
  /* 画像下文字サイズ */
  font-size: 0.8em;
  /* 画像下文字色 */
  color: #999;
}

.box-blink .inner-top .txt {
  margin: 0 2%;
}

.box-blink .inner-top .txt .title {
  /* 見出し文字サイズ */
  font-size: 1.6em;
  font-weight: 700;
  line-height: 1.2;
  margin: 0 0 10px;
}

.box-blink .inner-top .txt .inner-txt {
  display: flex;
  align-items: center;
  margin: 0;
  /* 金額文字サイズ */
  font-size: 2em;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.box-blink .inner-top .txt .inner-txt>span.double {
  font-size: 0.5em;
  line-height: 1.2;
  margin-right: 0.2em;
  white-space: nowrap;
}

.box-blink .inner-top .txt .inner-txt>span.slash {
  position: relative;
}

.box-blink .inner-top .txt .inner-txt>span.slash::before {
  content: "";
  position: absolute;
  top: 0.3em;
  width: 110%;
  /* 打ち消し線 */
  border-top: 6px solid #f00;
  -webkit-transform-origin: 0 0;
  transform-origin: 0 0;
  -webkit-transform: rotate(15deg);
  transform: rotate(15deg);
  -webkit-animation: blink 1.5s steps(1, start) infinite;
  animation: blink 1.5s steps(1, start) infinite;
}

.box-blink .inner-top .txt .inner-txt strong {
  /* 赤文字色 */
  color: #e32;
  font-weight: 700;
  font-style: normal;
  -webkit-animation: blink 1.5s steps(1, start) infinite;
  animation: blink 1.5s steps(1, start) infinite;
}

.box-blink .inner-top .txt .inner-txt strong::before {
  content: "⇒";
  position: relative;
  display: inline-block;
  font-size: 0.8em;
  margin: 0 0.2em;
}

.box-blink .inner-bottom {
