  margin: 1em 0;
  color: #666;
  line-height: 1.6;
}

.box-blink .inner-bottom>p:first-child {
  margin-top: 0;
}

.box-blink .inner-bottom>p:last-child {
  margin-bottom: 0;
}

@-webkit-keyframes blink {
  50% {
    opacity: 0;
  }
}

@keyframes blink {
  50% {
    opacity: 0;
  }
}

