  max-width: 580px;
  margin: 0 auto;
  padding: 0;
  text-align: center;
  box-sizing: border-box;
}

.box video,
.box iframe {
  width: 100%;
  margin: 0 !important;
  object-fit: cover;
}

.in:first-child {
  margin-top: 1em;
}

.in {
  position: relative;
  list-style: none;
  margin-bottom: 2em;
  /*枠内側の余白*/
  padding: 12px;
  /*線の指定。線の太さ、線の種類、線の色の順*/
  border: 1px solid #ffc7d3;
  /*枠内側の背景色*/
  background: #fff;
  /*角を丸くする*/
  border-radius: 6px;
}

.in .icon {
  position: absolute;
  top: -15px;
  left: -3px;
  padding-top: 10px;
  width: 60px;
  height: 60px;
  /*左上数字ラベルの背景色*/
  background-color: #0086ff;
  border-radius: 2em;
  background-size: 100% auto;
}

.in .icon .unit {
  font-size: 10px;
  display: block;
  color: #fff;
  line-height: 1;
}

span {
  margin: 0;
  padding: 0;
  border: 0;
  vertical-align: baseline;
  -webkit-box-sizing: border-box;
  -webkit-tap-highlight-color: rgba(0, 0, 0, 0);
}

.in .icon .number {
  line-height: 1;
  font-size: 30px;
  display: block;
  position: absolute;
  color: #fff;
  top: 35%;
  left: 20%;
}

