.review {
  /*最大幅の指定。max-widthで指定した値の最大幅以上には広がらずに表示*/
  max-width: 580px;
  /*行間調整*/
  line-height: 1.5;
  margin: 0 auto;
  box-sizing: border-box;
}

.in {
  box-sizing: border-box;
  position: relative;
  /*枠内側の余白*/
  padding: 12px;
  /*背景色*/
  background: #fff;
  /*角を丸くする*/
  border-radius: 6px;
  /*線の指定。左から線の太さ、線の種類、線の色*/
  border: 1px solid #ccc;
  /*影の指定。左から水平方向の距離、垂直方向の距離、影の色*/
  box-shadow: 3px 3px #ffc7d3;
}

.speech-bubble {
  /*吹き出しの背景色*/
  background-color: #ff7ba1;
  margin: 0 auto;
  /*吹き出しの内側の余白。左の値が上下、右の値が左右の余白*/
  padding: 10px;
  /*吹き出し文字の水平方向の位置。*/
  text-align: left;
  position: absolute;
  /*吹き出しの影。左から、水平方向の距離、垂直方向の距離、ぼかし距離、影の色の順*/
  box-shadow: 2px 2px 2px rgba(0, 0, 0, 0.3);
  border-radius: 6px;
  top: 0;
  left: 0;
  /*吹き出しの文字の色*/
  color: #fff;
  /*吹き出し文字の太さ*/
  font-weight: 600;
  /*吹き出し文字の影。左から、水平方向の距離、垂直方向の距離、ぼかし距離、影の色の順*/
  text-shadow: 1px 2px 3px #808080;
  /*水平方向の字間のスペース*/
  letter-spacing: .05em;
  max-width: 100%;
  box-sizing: border-box;
  width: auto;
}

.speech-bubble:after {
  content: "";
  position: absolute;
  /*吹き出しの影*/
  box-shadow: rgba(0, 0, 0, 0.3) 2px 2px 2px;
  -moz-transform: rotate(45deg);
  -webkit-transform: rotate(45deg);
  bottom: -7px;
  /*吹き出しのしっぽ部分の左からの距離*/
  left: 70%;
  /*吹き出しのしっぽの部分の背景色*/
  border-color: #ff7ba1;
  border-width: 7px;
  border-style: solid;
}

.kuchikomi {
  /*クチコミ部分の文章周りの余白。上の余白、左右の余白、下の余白*/
  margin: 12px 0;
}

.speech-bubble p {
  margin: 0;
}

