.qa {
  /*最大幅の指定。max-widthで指定した値の最大幅以上には広がらずに表示*/
  max-width: 580px;
  /*枠内側の余白。上｜左右｜下*/
  padding: 1em 1em 0;
  /*枠外側の余白。上下｜左右*/
  margin: 1em auto;
  /*ユーザー名の文字色*/
  color: #6091d3;
  /*枠内側の背景色*/
  background: #FFF;
  /*線の指定。線の太さ｜線の種類｜線の色*/
  border: 3px solid #6091d3;
  /*角を丸くする*/
  border-radius: 10px;
  box-sizing: border-box;
}

.profile {
  display: flex;
  align-items: center;
  padding-bottom: 1em;
}

.qa .icon {
  margin-right: 20px;
  /*画像サイズ。 変更する場合、下のpqa .icon imgの画像サイズも同様に変更ください*/
  width: 70px;
  height: auto;
}

.qa .icon img {
  /*画像サイズ*/
  width: 70px;
  /*画像最大サイズ*/
  max-width: 70px;
  /*画像の高さ*/
  height: 70px !important;
  /*角を丸くする。丸く芝居場合は下記削除*/
  border-radius: 50%;
  object-fit: cover;
  box-sizing: border-box;
}

.name {
  display: inline-block;
  position: relative;
}

.name dd {
  margin: 0;
  padding: 0;
  /*年齢 職業の文字色*/
  color: #8a9aa4;
  font-size: 70%;
}

.comment {
  color: black;
  padding: 0;
  margin: 0;
}

dl.comment dt {
  /*Q　質問の文字色*/
  color: black;
  padding: 0;
  font-weight: bold;
}

dl.comment dd {
  /*A　回答の文字色*/
  color: black;
  padding: 0 0 1em;
}

.red {
  /*spanタグ内文字色*/
  color: red;
}

.big {
  /*spanタグ内の文字サイズ*/
  font-size: 24px;
  /*spanタグ内の文字の太さ*/
  font-weight: 600;
}

blockquote {
  position: relative;
  /*最大幅の指定。max-widthで指定した値の最大幅以上には広がらずに表示*/
  max-width: 580px;
  /*枠外側の余白。上｜左右｜下*/
  margin: 0 auto 1.5em;
  /*枠内の余白。上｜左右｜下*/
  padding: 30px 15px 25px;
  /*線の指定。線の太さ｜線の種類｜線の色*/
  border: 2px solid #CCCCCC;
  /*背景色*/
  background-color: #F2F2F2;
  box-sizing: border-box;
}

blockquote:before {
  content: "“";
  /*左上引用符の色*/
  color: #CCCCCC;
  /*左上引用符の大きさ*/
  font-size: 500%;
  line-height: 0.8em;
  font-family: 'Times New Roman', sans-serif;
  position: absolute;
  left: 5px;
  top: 0;
}

blockquote:after {
  content: "”";
  /*右下引用符の色*/
  color: #CCCCCC;
  /*右下引用符の大きさ*/
  font-size: 500%;
  line-height: 0em;
  font-family: 'Times New Roman', sans-serif;
  position: absolute;
  right: 5px;
  bottom: 0;
}

